import Head from 'next/head'
import dynamic from 'next/dynamic'

/**
 * Spike: the landing scene rebuilt on react-three-fiber, served on its own
 * route so it can be compared against the legacy engine at `/` without
 * touching the live home.
 *
 * Not linked from anywhere. Delete this page once the port lands (or the spike
 * is abandoned).
 */
const Scene = dynamic(() => import('@home/scene/Scene').then((m) => m.Scene), { ssr: false })

export default function SpikeEscena() {
  return (
    <>
      <Head>
        <title>Spike · escena R3F</title>
        <meta name="robots" content="noindex" />
      </Head>
      <Scene />
    </>
  )
}
